  $steps=if($fr){@(@('⌕','Découverte','Nous comprenons vos objectifs, vos défis et vos priorités.'),@('▥','Analyse','Nous analysons vos processus et outils actuels.'),@('⌁','Conception','Nous concevons une solution adaptée à vos besoins.'),@('♢','Implantation','Nous développons, intégrons et formons votre équipe.'),@('↗','Optimisation','Nous mesurons les résultats et améliorons en continu.'))}else{@(@('⌕','Discovery','We understand your goals, challenges, and priorities.'),@('▥','Analysis','We analyze current processes and tools.'),@('⌁','Design','We design a solution around your needs.'),@('♢','Implementation','We build, integrate, and train your team.'),@('↗','Optimization','We measure results and improve continuously.'))}
  $processItems='';for($i=0;$i-lt$steps.Count;$i++){$n=$i+1;$processItems+="<li><span class=`"process-icon`">$($steps[$i][0])</span><h3><span>$n.</span> $($steps[$i][1])</h3><p>$($steps[$i][2])</p></li>"}
  $prow="<section class=`"process-row`"><div class=`"container row-inner`"><div class=`"row-intro`"><h2>$(if($fr){'Notre approche'}else{'Our approach'})</h2><p>$(if($fr){'Une approche collaborative et structurée pour des résultats durables.'}else{'A collaborative, structured approach for durable results.'})</p></div><ol class=`"process`">$processItems</ol></div></section>"
  return $hero+$srow+$trow+$urow+$prow
}

