 (MiniCard '/fr/outils/diagnostic-workflow/' '⌕' 'Diagnostic de workflow' 'Score de préparation et recommandations ciblées.')+(MiniCard '/fr/outils/calculateur-roi/' '▦' 'Calculateur ROI automation' 'Temps récupéré, économies et période de récupération.')+(MiniCard '/fr/outils/audit-express-pme/' '◴' 'Audit express PME' 'Priorités opérationnelles en 12 à 15 questions.')+(MiniCard '/fr/outils/generateur-cahier-besoins/' '▧' 'Générateur de cahier des besoins' 'Un brief structuré, copiable et imprimable.')+(MiniCard '/fr/outils/checklist-transformation-numerique/' '☑' 'Checklist de transformation numérique' 'Progression par catégorie et prochaines actions.')
}else{
 (MiniCard '/tools/workflow-diagnostic/' '⌕' 'Workflow diagnostic' 'Readiness score and focused recommendations.')+(MiniCard '/tools/roi-calculator/' '▦' 'Automation ROI calculator' 'Recovered time, savings, and payback period.')+(MiniCard '/tools/sme-express-audit/' '◴' 'SME express audit' 'Operating priorities in 12 to 15 questions.')+(MiniCard '/tools/requirements-brief-generator/' '▧' 'Requirements brief generator' 'A structured, copyable, printable brief.')+(MiniCard '/tools/digital-transformation-checklist/' '☑' 'Digital transformation checklist' 'Category progress and next actions.')
