function DiagnosticBody([string]$Lang){$fr=$Lang-eq'fr';$questions=if($fr){@('Le processus est exécuté fréquemment.','Il demande beaucoup de temps manuel.','Les mêmes données sont saisies dans plusieurs systèmes.','Il implique des transferts ou suivis entre personnes.','Les entrées suivent un format assez constant.','Les erreurs ou oublis entraînent du retraitement.','Les règles de décision sont généralement explicites.','Un responsable peut participer au projet.','Le volume ou le temps actuel peut être mesuré.','Le délai affecte clients, revenus ou capacité.','Les systèmes offrent des exports ou intégrations.')}else{@('The process is performed frequently.','It requires substantial manual time.','The same data is entered in multiple systems.','It has handoffs or follow-ups between people.','Inputs follow a reasonably consistent format.','Errors or omissions lead to rework.','Decision rules are generally explicit.','A process owner can participate.','Current volume or effort can be measured.','Delays affect customers, revenue, or capacity.','Systems support exports or integrations.')};$fields='';for($i=0;$i-lt$questions.Count;$i++){$n=$i+1;$fields+="<fieldset><legend>$n. $($questions[$i])</legend><div class=`"choices`"><label class=`"choice`"><input required type=`"radio`" name=`"q$n`" value=`"0`">0 — $(if($fr){'Faible'}else{'Low'})</label><label class=`"choice`"><input type=`"radio`" name=`"q$n`" value=`"2`">2 — $(if($fr){'Moyen'}else{'Medium'})</label><label class=`"choice`"><input type=`"radio`" name=`"q$n`" value=`"4`">4 — $(if($fr){'Élevé'}else{'High'})</label></div></fieldset>"};return (PageHero $(if($fr){'OUTIL 01'}else{'TOOL 01'}) $(if($fr){'Diagnostic de workflow'}else{'Workflow diagnostic'}) $(if($fr){'Évaluez un processus précis et obtenez un score de préparation à l&rsquo;automatisation sur 100.'}else{'Assess one specific process and receive an automation-readiness score out of 100.'}))+"<section class=`"section`"><div class=`"container`"><div class=`"tool-shell`"><form class=`"form-grid`" data-diagnostic>$fields<button class=`"button`" type=`"submit`">$(if($fr){'Calculer mon score'}else{'Calculate my score'})</button></form><div class=`"tool-result`" data-diagnostic-result aria-live=`"polite`"><div class=`"score`" data-score-ring>0/100</div><h2 data-score-title></h2><p data-score-summary></p><h3>$(if($fr){'Trois recommandations'}else{'Three recommendations'})</h3><ol data-recommendations></ol><button class=`"button secondary no-print`" type=`"button`" onclick=`"window.print()`">$(if($fr){'Imprimer'}else{'Print'})</button></div></div></div></section>"}
Save-Page 'tools/workflow-diagnostic/index.html' (Page 'en' 'Workflow diagnostic — Delta Operations' 'Assess automation readiness with an eleven-question local workflow diagnostic.' '/tools/workflow-diagnostic/' '/fr/outils/diagnostic-workflow/' 'tools' (DiagnosticBody 'en') '<script src="/assets/js/tools.js"></script>')
Save-Page 'fr/outils/diagnostic-workflow/index.html' (Page 'fr' 'Diagnostic de workflow — Opérations Delta' 'Évaluez la préparation à l&rsquo;automatisation avec onze questions locales.' '/fr/outils/diagnostic-workflow/' '/tools/workflow-diagnostic/' 'tools' (DiagnosticBody 'fr') '<script src="/assets/js/tools.js"></script>')

function RoiBody([string]$Lang){$fr=$Lang-eq'fr';return (PageHero $(if($fr){'OUTIL 02'}else{'TOOL 02'}) $(if($fr){'Calculateur ROI automation'}else{'Automation ROI calculator'}) $(if($fr){'Estimez le temps récupéré, les économies et la période de récupération en dollars canadiens.'}else{'Estimate recovered time, savings, and payback in Canadian dollars.'}))+@"
<section class="section"><div class="container"><div class="tool-shell"><form data-roi class="form-grid two">
<div class="field"><label for="hours">$(if($fr){'Heures par semaine consacrées à la tâche'}else{'Hours per week spent on the task'})</label><input id="hours" name="hours" type="number" min="0" step=".5" value="10" required></div>
<div class="field"><label for="employees">$(if($fr){'Nombre d&rsquo;employés concernés'}else{'Employees involved'})</label><input id="employees" name="employees" type="number" min="1" value="2" required></div>
<div class="field"><label for="hourly">$(if($fr){'Coût horaire chargé (CAD)'}else{'Loaded hourly cost (CAD)'})</label><input id="hourly" name="hourly" type="number" min="0" value="45" required></div>
<div class="field"><label for="automatable">$(if($fr){'Part automatisable (%)'}else{'Work that could be automated (%)'})</label><input id="automatable" name="automatable" type="number" min="0" max="100" value="60" required></div>
<div class="field"><label for="project">$(if($fr){'Coût estimé du projet (CAD)'}else{'Estimated project cost (CAD)'})</label><input id="project" name="project" type="number" min="0" value="15000" required></div><button class="button" type="submit">$(if($fr){'Calculer'}else{'Calculate'})</button></form>
<div class="tool-result" data-roi-result aria-live="polite"><div class="metrics"><div class="metric">$(if($fr){'Heures récupérées/mois'}else{'Hours recovered/month'})<strong data-hours></strong></div><div class="metric">$(if($fr){'Économie mensuelle'}else{'Monthly savings'})<strong data-monthly></strong></div><div class="metric">$(if($fr){'Économie annuelle'}else{'Annual savings'})<strong data-annual></strong></div><div class="metric">$(if($fr){'Récupération'}else{'Payback'})<strong data-payback></strong></div></div><h3>$(if($fr){'Fourchettes annuelles'}else{'Annual ranges'})</h3><div class="grid three" data-scenarios></div><p class="hint">$(if($fr){'Estimation indicative : exclut les coûts récurrents, la courbe d&rsquo;adoption et les bénéfices non financiers.'}else{'Indicative estimate: excludes recurring costs, adoption ramp, and non-financial benefits.'})</p><button class="button secondary no-print" type="button" onclick="window.print()">$(if($fr){'Imprimer'}else{'Print'})</button></div></div></div></section>
"@}
Save-Page 'tools/roi-calculator/index.html' (Page 'en' 'Automation ROI calculator — Delta Operations' 'Estimate automation savings and payback locally in your browser.' '/tools/roi-calculator/' '/fr/outils/calculateur-roi/' 'tools' (RoiBody 'en') '<script src="/assets/js/tools.js"></script>')
Save-Page 'fr/outils/calculateur-roi/index.html' (Page 'fr' 'Calculateur ROI automation — Opérations Delta' 'Estimez localement les économies et le délai de récupération d&rsquo;une automatisation.' '/fr/outils/calculateur-roi/' '/tools/roi-calculator/' 'tools' (RoiBody 'fr') '<script src="/assets/js/tools.js"></script>')

function BriefBody([string]$Lang){$fr=$Lang-eq'fr';return (PageHero $(if($fr){'OUTIL 04'}else{'TOOL 04'}) $(if($fr){'Générateur de cahier des besoins'}else{'Requirements brief generator'}) $(if($fr){'Transformez une idée en brief structuré. Rien n&rsquo;est enregistré ni envoyé.'}else{'Turn an idea into a structured brief. Nothing is saved or submitted.'}))+@"
<section class="section"><div class="container"><div class="tool-shell"><form data-brief class="form-grid"><p><strong data-brief-progress></strong></p>
<div data-brief-step><h2>$(if($fr){'Processus et utilisateurs'}else{'Workflow and users'})</h2><div class="field"><label for="workflow">$(if($fr){'Décrivez le workflow actuel'}else{'Describe the current workflow'}) *</label><textarea id="workflow" name="workflow" required></textarea></div><div class="field"><label for="users">$(if($fr){'Qui utilise ou influence le processus?'}else{'Who uses or influences the process?'}) *</label><textarea id="users" name="users" required></textarea></div><button class="button" type="button" data-next>$(if($fr){'Suivant'}else{'Next'})</button></div>
<div data-brief-step hidden><h2>$(if($fr){'Informations et résultats'}else{'Information and outcomes'})</h2><div class="field"><label for="inputs">$(if($fr){'Entrées et sources'}else{'Inputs and sources'}) *</label><textarea id="inputs" name="inputs" required></textarea></div><div class="field"><label for="outputs">$(if($fr){'Sorties attendues'}else{'Expected outputs'}) *</label><textarea id="outputs" name="outputs" required></textarea></div><button class="button secondary" type="button" data-previous>$(if($fr){'Précédent'}else{'Previous'})</button> <button class="button" type="button" data-next>$(if($fr){'Suivant'}else{'Next'})</button></div>
<div data-brief-step hidden><h2>$(if($fr){'Automatisation et intégrations'}else{'Automation and integrations'})</h2><div class="field"><label for="automations">$(if($fr){'Automatisations souhaitées'}else{'Desired automations'}) *</label><textarea id="automations" name="automations" required></textarea></div><div class="field"><label for="integrations">$(if($fr){'Logiciels, fichiers ou systèmes à intégrer'}else{'Software, files, or systems to integrate'})</label><textarea id="integrations" name="integrations"></textarea></div><button class="button secondary" type="button" data-previous>$(if($fr){'Précédent'}else{'Previous'})</button> <button class="button" type="button" data-next>$(if($fr){'Suivant'}else{'Next'})</button></div>
<div data-brief-step hidden><h2>$(if($fr){'Contraintes et succès'}else{'Constraints and success'})</h2><div class="field"><label for="constraints">$(if($fr){'Contraintes et exigences'}else{'Constraints and requirements'}) *</label><textarea id="constraints" name="constraints" required></textarea></div><div class="field"><label for="deadline">$(if($fr){'Échéance'}else{'Deadline'})</label><input id="deadline" name="deadline"></div><div class="field"><label for="success">$(if($fr){'Critères de succès'}else{'Success criteria'}) *</label><textarea id="success" name="success" required></textarea></div><button class="button secondary" type="button" data-previous>$(if($fr){'Précédent'}else{'Previous'})</button> <button class="button" type="submit">$(if($fr){'Générer'}else{'Generate'})</button></div></form>
<div class="tool-result" data-brief-result aria-live="polite"><div class="brief-output" data-brief-output></div><p class="no-print"><button class="button" type="button" data-copy-brief>$(if($fr){'Copier'}else{'Copy'})</button> <button class="button secondary" type="button" data-print>$(if($fr){'Imprimer / PDF'}else{'Print / PDF'})</button></p></div></div></div></section>
"@}
Save-Page 'tools/requirements-brief-generator/index.html' (Page 'en' 'Requirements brief generator — Delta Operations' 'Generate a structured project requirements brief locally in your browser.' '/tools/requirements-brief-generator/' '/fr/outils/generateur-cahier-besoins/' 'tools' (BriefBody 'en') '<script src="/assets/js/tools.js"></script>')
