function AuditBody([string]$Lang){$fr=$Lang-eq'fr';$questions=if($fr){@('Nos processus clés sont documentés et compris.','Les tâches répétitives sont identifiées et mesurées.','L&rsquo;information entre une seule fois dans nos systèmes.','Les responsabilités et transferts sont clairs.','Les délais et files d&rsquo;attente sont visibles.','Les erreurs et reprises sont mesurées.','Nos outils répondent encore aux besoins actuels.','Les systèmes peuvent échanger des données.','Les données importantes sont structurées et fiables.','Les indicateurs opérationnels sont disponibles rapidement.','Les accès et renseignements sensibles sont contrôlés.','Une personne est responsable de chaque processus clé.','Les équipes participent aux changements d&rsquo;outils.','Nous avons une liste priorisée d&rsquo;améliorations.')}else{@('Our key processes are documented and understood.','Repetitive tasks are identified and measured.','Information enters our systems only once.','Responsibilities and handoffs are clear.','Delays and queues are visible.','Errors and rework are measured.','Our tools still meet current needs.','Systems can exchange data.','Important data is structured and reliable.','Operating metrics are available quickly.','Access and sensitive information are controlled.','One person owns each key process.','Teams participate in tool changes.','We have a prioritized improvement list.')};$fields='';for($i=0;$i-lt$questions.Count;$i++){$n=$i+1;$fields+="<fieldset><legend>$n. $($questions[$i])</legend><div class=`"choices`"><label class=`"choice`"><input required type=`"radio`" name=`"a$n`" value=`"0`">$(if($fr){'Non / inconnu'}else{'No / unknown'})</label><label class=`"choice`"><input type=`"radio`" name=`"a$n`" value=`"1`">$(if($fr){'En partie'}else{'Partly'})</label><label class=`"choice`"><input type=`"radio`" name=`"a$n`" value=`"2`">$(if($fr){'Oui, de façon fiable'}else{'Yes, reliably'})</label></div></fieldset>"};return (PageHero $(if($fr){'OUTIL 03'}else{'TOOL 03'}) $(if($fr){'Audit express PME'}else{'SME express audit'}) $(if($fr){'Évaluez la maturité des processus, des données et des outils en environ 15 minutes.'}else{'Assess process, data, and tool maturity in about 15 minutes.'}))+"<section class=`"section`"><div class=`"container`"><div class=`"tool-shell`"><form data-sme-audit class=`"form-grid`">$fields<button class=`"button`" type=`"submit`">$(if($fr){'Analyser mes réponses'}else{'Analyze my answers'})</button></form><div class=`"tool-result`" data-audit-result aria-live=`"polite`"><h2 data-audit-title></h2><p data-audit-summary></p><h3>$(if($fr){'Trois occasions prioritaires'}else{'Three priority opportunities'})</h3><ol data-audit-opportunities></ol><h3>$(if($fr){'Prochaines étapes recommandées'}else{'Recommended next steps'})</h3><ul data-audit-next></ul><button class=`"button secondary no-print`" type=`"button`" data-print>$(if($fr){'Imprimer'}else{'Print'})</button></div></div></div></section>"}
Save-Page 'tools/sme-express-audit/index.html' (Page 'en' 'SME express audit — Delta Operations' 'A local fourteen-question audit of process, data, and tool maturity.' '/tools/sme-express-audit/' '/fr/outils/audit-express-pme/' 'tools' (AuditBody 'en') '<script src="/assets/js/tools.js"></script>')
Save-Page 'fr/outils/audit-express-pme/index.html' (Page 'fr' 'Audit express PME — Opérations Delta' 'Un audit local de quatorze questions sur les processus, données et outils.' '/fr/outils/audit-express-pme/' '/tools/sme-express-audit/' 'tools' (AuditBody 'fr') '<script src="/assets/js/tools.js"></script>')

function ChecklistBody([string]$Lang){$fr=$Lang-eq'fr';$groups=if($fr){[ordered]@{'Opérations'=@('Les processus clés sont documentés','Un responsable est nommé par processus','Les exceptions sont connues');'Données'=@('Les sources de données sont identifiées','Les définitions importantes sont communes','La qualité est vérifiée régulièrement');'Communications'=@('Les canaux et responsabilités sont clairs','Les demandes ont un point d&rsquo;entrée défini','Les suivis ne reposent pas sur la mémoire');'Sécurité'=@('Les accès suivent les rôles','Les données sensibles sont identifiées','Sauvegarde et récupération sont testées');'Intégrations'=@('Les doubles saisies sont inventoriées','Les capacités API/export sont connues','Un système de référence est défini');'Rapports'=@('Les indicateurs ont une définition','Les rapports ont un propriétaire','Les écarts déclenchent une action')}}else{[ordered]@{'Operations'=@('Key processes are documented','Each process has an owner','Known exceptions are documented');'Data'=@('Data sources are identified','Important definitions are shared','Quality is checked regularly');'Communications'=@('Channels and responsibilities are clear','Requests have a defined entry point','Follow-up does not depend on memory');'Security'=@('Access follows job roles','Sensitive data is identified','Backup and recovery are tested');'Integrations'=@('Duplicate entry is inventoried','API and export capabilities are known','A system of record is defined');'Reporting'=@('Metrics have clear definitions','Reports have an owner','Variance triggers action')}};$html='';$idx=0;foreach($g in $groups.GetEnumerator()){$checks='';foreach($item in $g.Value){$idx++;$checks+="<label class=`"choice`"><input type=`"checkbox`" name=`"check$idx`" value=`"$($g.Key)`">$item</label>"};$html+="<fieldset data-category=`"$($g.Key)`"><legend>$($g.Key)</legend><div class=`"choices`">$checks</div></fieldset>"};return (PageHero $(if($fr){'OUTIL 05'}else{'TOOL 05'}) $(if($fr){'Checklist de transformation numérique'}else{'Digital transformation checklist'}) $(if($fr){'Évaluez six fondations essentielles. Votre progression est sauvegardée uniquement dans ce navigateur.'}else{'Assess six essential foundations. Progress is saved only in this browser.'}))+"<section class=`"section`"><div class=`"container`"><div class=`"tool-shell`" data-checklist data-storage-key=`"opdelta-checklist-$Lang`"><form class=`"form-grid`">$html</form><div class=`"tool-result visible`" aria-live=`"polite`"><h2>$(if($fr){'Progression globale'}else{'Overall progress'}): <span data-checklist-score>0%</span></h2><div class=`"progress-bars`" data-category-progress></div><h3>$(if($fr){'Prochaines actions'}else{'Next actions'})</h3><ol data-checklist-actions></ol><p class=`"no-print`"><button class=`"button secondary`" type=`"button`" data-checklist-reset>$(if($fr){'Réinitialiser'}else{'Reset'})</button> <button class=`"button`" type=`"button`" data-print>$(if($fr){'Imprimer'}else{'Print'})</button></p></div></div></div></section>"}
Save-Page 'tools/digital-transformation-checklist/index.html' (Page 'en' 'Digital transformation checklist — Delta Operations' 'Interactive local checklist for operations, data, communication, security, integrations, and reporting.' '/tools/digital-transformation-checklist/' '/fr/outils/checklist-transformation-numerique/' 'tools' (ChecklistBody 'en') '<script src="/assets/js/tools.js"></script>')
Save-Page 'fr/outils/checklist-transformation-numerique/index.html' (Page 'fr' 'Checklist de transformation numérique — Opérations Delta' 'Checklist locale pour opérations, données, communications, sécurité, intégrations et rapports.' '/fr/outils/checklist-transformation-numerique/' '/tools/digital-transformation-checklist/' 'tools' (ChecklistBody 'fr') '<script src="/assets/js/tools.js"></script>')

function ContactBody([string]$Lang){$fr=$Lang-eq'fr';return (PageHero 'CONTACT' $(if($fr){'Parlez-nous du processus qui vous ralentit.'}else{'Tell us about the process slowing you down.'}) $(if($fr){'Vous n&rsquo;avez pas besoin de connaître la solution. Décrivez le problème, le contexte et le résultat souhaité.'}else{'You do not need to know the solution. Describe the problem, context, and desired outcome.'}))+@"
<section class="section"><div class="container"><div class="grid two"><div><article class="card"><h2>$(if($fr){'Écrivez-nous directement'}else{'Email us directly'})</h2><p><a href="mailto:contact@deltaoperations.ca">contact@deltaoperations.ca</a></p><p>Montréal, Québec<br>$(if($fr){'Disponible partout au Québec'}else{'Available across Québec'})</p></article><article class="card" style="margin-top:1rem"><h2>$(if($fr){'Contexte utile'}else{'Helpful context'})</h2><ul><li>$(if($fr){'Le processus actuel et les personnes concernées'}else{'The current process and people involved'})</li><li>$(if($fr){'Ce qui prend trop de temps ou cause des erreurs'}else{'What takes too long or causes errors'})</li><li>$(if($fr){'Les outils déjà utilisés'}else{'Tools already in use'})</li><li>$(if($fr){'Le résultat souhaité et l&rsquo;échéance'}else{'Desired outcome and timeline'})</li></ul></article></div>
<form class="card form-grid" data-contact-form action="https://formspree.io/f/xzdnzlnr" method="POST"><input type="hidden" name="_subject" value="$(if($fr){'Nouveau contact — Opérations Delta'}else{'New contact — Delta Operations'})"><input type="hidden" name="language" value="$Lang">
<h2>$(if($fr){'Demander un audit'}else{'Request an audit'})</h2><div class="field"><label for="name">$(if($fr){'Nom'}else{'Name'}) *</label><input id="name" name="name" autocomplete="name" required></div><div class="field"><label for="email">$(if($fr){'Courriel'}else{'Email'}) *</label><input id="email" name="email" type="email" autocomplete="email" required></div><div class="field"><label for="organization">$(if($fr){'Organisation'}else{'Organization'})</label><input id="organization" name="organization" autocomplete="organization"></div><div class="field"><label for="problem">$(if($fr){'Problème opérationnel actuel'}else{'Current operational problem'}) *</label><textarea id="problem" name="problem" required></textarea></div><div class="field"><label for="scope">$(if($fr){'Portée approximative du projet'}else{'Approximate project scope'})</label><select id="scope" name="scope"><option value="">$(if($fr){'À déterminer'}else{'To be determined'})</option><option>$(if($fr){'Audit seulement'}else{'Audit only'})</option><option>$(if($fr){'Automatisation ciblée'}else{'Focused automation'})</option><option>$(if($fr){'Système ou intégration'}else{'System or integration'})</option><option>$(if($fr){'Programme par étapes'}else{'Phased program'})</option></select></div><div class="field"><label for="preferred-language">$(if($fr){'Langue préférée'}else{'Preferred language'})</label><select id="preferred-language" name="preferred_language"><option>Français</option><option>English</option></select></div><label class="consent"><input type="checkbox" name="consent" value="yes" required><span>$(if($fr){'J&rsquo;accepte qu&rsquo;Opérations Delta utilise ces renseignements pour répondre à ma demande.'}else{'I agree that Delta Operations may use this information to respond to my request.'}) <a href="$(if($fr){'/fr/confidentialite/'}else{'/privacy/'})">$(if($fr){'Confidentialité'}else{'Privacy'})</a>.</span></label><button class="button" type="submit">$(if($fr){'Envoyer'}else{'Send'})</button><p class="status" data-form-status role="status" aria-live="polite"></p></form></div></div></section>
"@}
Save-Page 'contact/index.html' (Page 'en' 'Contact — Delta Operations' 'Request an operational audit or discuss an automation, AI, data, or custom-system project.' '/contact/' '/fr/contact/' 'contact' (ContactBody 'en'))
Save-Page 'fr/contact/index.html' (Page 'fr' 'Contact — Opérations Delta' 'Demandez un audit opérationnel ou discutez d&rsquo;un projet d&rsquo;automatisation, d&rsquo;IA, de données ou de système.' '/fr/contact/' '/contact/' 'contact' (ContactBody 'fr'))

function ResourcesBody([string]$Lang){$fr=$Lang-eq'fr';$items=if($fr){@(@('FAQ','Réponses claires sur coûts, délais, sécurité, IA et soutien.','/fr/faq/'),@('Études de cas','Scénarios représentatifs clairement identifiés, sans faux clients.','/fr/etudes-de-cas/'),@('Guides pratiques','Guides écrits pour cadrer un audit et préparer une automatisation.','/fr/guides/'),@('Modèles','Canevas utiles et liens vers les outils interactifs.','/fr/modeles/'),@('Vidéos explicatives','Résumés écrits pendant la préparation des vidéos.','/fr/videos/'))}else{@(@('FAQ','Clear answers about cost, timelines, security, AI, and support.','/faq/'),@('Case studies','Clearly labeled representative scenarios with no fictional client claims.','/case-studies/'),@('Practical guides','Written guidance for scoping audits and preparing automation.','/guides/'),@('Templates','Useful working structures and links to interactive tools.','/templates/'),@('Explainer videos','Useful written summaries while videos are being prepared.','/videos/'))};$html='';for($i=0;$i-lt$items.Count;$i++){$html+="<article class=`"resource-item`"><span>0$($i+1)</span><div><h2>$($items[$i][0])</h2><p>$($items[$i][1])</p></div><a href=`"$($items[$i][2])`">$(if($fr){'Consulter'}else{'Open'}) →</a></article>"};return (PageHero $(if($fr){'RESSOURCES'}else{'RESOURCES'}) $(if($fr){'Des ressources utiles, sans bruit.'}else{'Useful resources without the noise.'}) $(if($fr){'Pas de blogue générique : des réponses, scénarios, guides et outils pratiques.'}else{'No generic blog: practical answers, scenarios, guides, and tools.'}))+"<section class=`"section`"><div class=`"container resource-list`">$html</div></section>"}
Save-Page 'resources/index.html' (Page 'en' 'Resources — Delta Operations' 'FAQ, representative scenarios, practical guides, templates, and explainer resources.' '/resources/' '/fr/ressources/' '' (ResourcesBody 'en'))
Save-Page 'fr/ressources/index.html' (Page 'fr' 'Ressources — Opérations Delta' 'FAQ, scénarios représentatifs, guides, modèles et ressources explicatives.' '/fr/ressources/' '/resources/' '' (ResourcesBody 'fr'))

$faqEn=(PageHero 'FAQ' 'Straight answers before you start.' 'Common questions from Québec small businesses evaluating operational improvement.')+'<section class="section"><div class="container faq">'+(@(
@('What does a project cost?','Cost depends on scope, systems, data quality, risk, and the level of change required. A short audit is used to define options and an estimate before a build commitment.'),
@('How long does a project take?','A focused diagnostic can take days or weeks; implementation may range from a small prototype to a phased program. The timeline is confirmed after scope and dependencies are understood.'),
@('What happens in a process audit?','We map the workflow, interview the people involved, identify volume and exceptions, review existing tools, and prioritize opportunities by value, effort, and risk.'),
@('How is data protected?','The design should minimize collection, restrict access, document data flow, and use appropriate provider controls. Requirements are assessed for each project; highly sensitive data needs additional review.'),
@('Will artificial intelligence replace employees?','The goal is to reduce repetitive work and support better decisions. AI should retain human review where errors, ambiguity, privacy, or accountability matter.'),
@('Can you integrate our existing software?','Often, yes. Feasibility depends on APIs, exports, permissions, licensing, and data quality. These constraints are checked before an integration is promised.'),
@('What support is available after launch?','Support can include documentation, training, monitoring, issue response, and measured optimization based on the agreed engagement.'),
@('Who owns a custom system?','Ownership, licenses, credentials, hosting, and third-party components should be defined explicitly in the project agreement before work begins.'),
@('Do you work with Québec SMEs in French and English?','Yes. Discovery, documentation, interfaces, and support can be delivered in French or English for organizations across Québec.')
)|ForEach-Object{"<details><summary>$($_[0])</summary><p>$($_[1])</p></details>"})-join''+'</div></section>'
$faqFr=(PageHero 'FAQ' 'Des réponses claires avant de commencer.' 'Questions fréquentes des PME québécoises qui évaluent une amélioration opérationnelle.')+'<section class="section"><div class="container faq">'+(@(
@('Combien coûte un projet?','Le coût dépend de la portée, des systèmes, de la qualité des données, du risque et du changement requis. Un audit permet de définir les options et une estimation avant l&rsquo;engagement de construction.'),
@('Combien de temps prend un projet?','Un diagnostic ciblé peut prendre quelques jours ou semaines; l&rsquo;implantation varie d&rsquo;un petit prototype à un programme par étapes. L&rsquo;échéancier est confirmé après l&rsquo;analyse des dépendances.'),
@('Que comprend un audit des processus?','Nous cartographions le workflow, rencontrons les personnes, évaluons le volume et les exceptions, examinons les outils et priorisons selon la valeur, l&rsquo;effort et le risque.'),
@('Comment les données sont-elles protégées?','La conception doit minimiser la collecte, limiter les accès, documenter les flux et utiliser les contrôles appropriés. Les données très sensibles exigent une analyse supplémentaire.'),
@('L&rsquo;intelligence artificielle remplacera-t-elle des employés?','L&rsquo;objectif est de réduire le travail répétitif et soutenir les décisions. Une validation humaine demeure nécessaire lorsque l&rsquo;erreur, l&rsquo;ambiguïté ou la confidentialité comptent.'),
@('Pouvez-vous intégrer nos logiciels existants?','Souvent oui. La faisabilité dépend des API, exports, permissions, licences et de la qualité des données. Ces contraintes sont vérifiées avant toute promesse.'),
@('Quel soutien est offert après le lancement?','Le soutien peut comprendre documentation, formation, surveillance, réponse aux problèmes et optimisation mesurée selon le mandat.'),
@('Qui possède un système sur mesure?','La propriété, les licences, accès, hébergement et composantes tierces doivent être définis clairement dans l&rsquo;entente avant le début du travail.'),
@('Travaillez-vous avec les PME en français et en anglais?','Oui. Découverte, documentation, interfaces et soutien peuvent être livrés dans les deux langues partout au Québec.')
)|ForEach-Object{"<details><summary>$($_[0])</summary><p>$($_[1])</p></details>"})-join''+'</div></section>'
Save-Page 'faq/index.html' (Page 'en' 'FAQ — Delta Operations' 'Answers about automation project cost, timelines, security, AI, integrations, support, and ownership.' '/faq/' '/fr/faq/' '' $faqEn)
Save-Page 'fr/faq/index.html' (Page 'fr' 'FAQ — Opérations Delta' 'Réponses sur les coûts, délais, sécurité, IA, intégrations, soutien et propriété.' '/fr/faq/' '/faq/' '' $faqFr)

function ScenarioBody([string]$Lang){$fr=$Lang-eq'fr';$cards=if($fr){@(@('Scénario représentatif','Intake de demandes pour une firme de services','Un point d&rsquo;entrée structuré valide les champs, crée le dossier, attribue le responsable et confirme la réception.','Ce scénario illustre une architecture possible; il ne représente pas un client nommé ni des résultats mesurés.'),@('Scénario représentatif','Soumissions pour une entreprise de métiers','Les données de portée sont recueillies une fois, les règles de prix sont appliquées, puis la soumission suit une approbation et des relances.','Les économies dépendent du volume, des exceptions et des systèmes existants.'),@('Scénario représentatif','Rapports opérationnels pour un distributeur','Des données validées alimentent un rapport périodique axé sur les écarts, les ruptures et les actions requises.','Aucun résultat financier réel n&rsquo;est revendiqué.'))}else{@(@('Representative scenario','Request intake for a service firm','One structured entry point validates fields, creates the file, assigns an owner, and confirms receipt.','This illustrates a possible architecture; it is not a named client or measured result.'),@('Representative scenario','Quoting for a trades business','Scope data is collected once, pricing rules are applied, and the quote moves through approval and follow-up.','Savings depend on volume, exceptions, and existing systems.'),@('Representative scenario','Operating reports for a distributor','Validated data feeds a scheduled exception-oriented report covering shortages, variance, and required action.','No real financial outcome is claimed.'))};$html=($cards|ForEach-Object{"<article class=`"card`"><p class=`"eyebrow`">$($_[0])</p><h2>$($_[1])</h2><p>$($_[2])</p><div class=`"notice`">$($_[3])</div></article>"})-join'';return (PageHero $(if($fr){'ÉTUDES DE CAS'}else{'CASE STUDIES'}) $(if($fr){'Scénarios représentatifs, présentés honnêtement.'}else{'Representative scenarios, presented honestly.'}) $(if($fr){'Ces exemples montrent comment une solution pourrait être conçue. Ils ne prétendent pas représenter des clients réels.'}else{'These examples show how a solution could be designed. They do not claim to represent real clients.'}))+"<section class=`"section`"><div class=`"container grid three`">$html</div></section>"}
Save-Page 'case-studies/index.html' (Page 'en' 'Representative project scenarios — Delta Operations' 'Honest representative automation and operations scenarios, not fictional client claims.' '/case-studies/' '/fr/etudes-de-cas/' '' (ScenarioBody 'en'))
Save-Page 'fr/etudes-de-cas/index.html' (Page 'fr' 'Scénarios de projets représentatifs — Opérations Delta' 'Scénarios honnêtes d&rsquo;automatisation, sans faux clients ni résultats inventés.' '/fr/etudes-de-cas/' '/case-studies/' '' (ScenarioBody 'fr'))

function GuidesBody([string]$Lang){$fr=$Lang-eq'fr';$cards=if($fr){@(@('Préparer un audit de processus','Choisissez un processus précis, identifiez son début et sa fin, réunissez deux ou trois personnes qui le connaissent et apportez volume, délais, erreurs et exemples réels.'),@('Évaluer une automatisation','Vérifiez fréquence, règles, qualité des entrées, exceptions, systèmes, propriétaire et mesure de référence avant de sélectionner un outil.'),@('Préparer les données','Nommez la source de référence, définissez les champs importants, repérez les doublons et confirmez les règles d&rsquo;accès et de conservation.'),@('Planifier l&rsquo;adoption','Impliquez les utilisateurs tôt, testez avec des cas réels, documentez la reprise manuelle et mesurez l&rsquo;utilisation après le lancement.'))}else{@(@('Prepare for a process audit','Choose one specific process, define its start and end, involve two or three people who know it, and bring real volume, delay, error, and example data.'),@('Assess an automation','Check frequency, rules, input quality, exceptions, systems, ownership, and baseline measures before selecting a tool.'),@('Prepare the data','Name the system of record, define important fields, find duplicates, and confirm access and retention rules.'),@('Plan adoption','Involve users early, test with real cases, document manual recovery, and measure use after launch.'))};$html=($cards|ForEach-Object{"<article class=`"card`"><h2>$($_[0])</h2><p>$($_[1])</p></article>"})-join'';return (PageHero $(if($fr){'GUIDES'}else{'GUIDES'}) $(if($fr){'Des repères pratiques pour mieux préparer le travail.'}else{'Practical guidance for better preparation.'}) $(if($fr){'Des guides courts qui complètent les outils interactifs.'}else{'Short guides that complement the interactive tools.'}))+"<section class=`"section`"><div class=`"container grid two`">$html</div></section>"}
Save-Page 'guides/index.html' (Page 'en' 'Practical guides — Delta Operations' 'Practical guidance for process audits, automation, data preparation, and adoption.' '/guides/' '/fr/guides/' '' (GuidesBody 'en'))
Save-Page 'fr/guides/index.html' (Page 'fr' 'Guides pratiques — Opérations Delta' 'Guides pratiques pour audits, automatisation, préparation des données et adoption.' '/fr/guides/' '/guides/' '' (GuidesBody 'fr'))

function TemplatesBody([string]$Lang){$fr=$Lang-eq'fr';return (PageHero $(if($fr){'MODÈLES'}else{'TEMPLATES'}) $(if($fr){'Des structures de travail réutilisables.'}else{'Reusable working structures.'}) $(if($fr){'Utilisez les outils interactifs pour produire une première version adaptée à votre contexte.'}else{'Use the interactive tools to produce a first draft adapted to your context.'}))+"<section class=`"section`"><div class=`"container grid three`">"+(MiniCard $(if($fr){'/fr/outils/diagnostic-workflow/'}else{'/tools/workflow-diagnostic/'}) '⌕' $(if($fr){'Grille de diagnostic'}else{'Diagnostic worksheet'}) $(if($fr){'Évaluer un workflow en onze questions.'}else{'Assess a workflow in eleven questions.'}))+(MiniCard $(if($fr){'/fr/outils/generateur-cahier-besoins/'}else{'/tools/requirements-brief-generator/'}) '▧' $(if($fr){'Cahier des besoins'}else{'Requirements brief'}) $(if($fr){'Générer une structure à copier ou imprimer.'}else{'Generate a structure to copy or print.'}))+(MiniCard $(if($fr){'/fr/outils/checklist-transformation-numerique/'}else{'/tools/digital-transformation-checklist/'}) '☑' $(if($fr){'Checklist de préparation'}else{'Readiness checklist'}) $(if($fr){'Suivre six catégories de fondation.'}else{'Track six foundation categories.'}))+"</div></section>"}
Save-Page 'templates/index.html' (Page 'en' 'Templates — Delta Operations' 'Reusable workflow diagnostic, requirements brief, and transformation-readiness structures.' '/templates/' '/fr/modeles/' '' (TemplatesBody 'en'))
Save-Page 'fr/modeles/index.html' (Page 'fr' 'Modèles — Opérations Delta' 'Structures réutilisables de diagnostic, cahier des besoins et préparation numérique.' '/fr/modeles/' '/templates/' '' (TemplatesBody 'fr'))

function VideosBody([string]$Lang){$fr=$Lang-eq'fr';return (PageHero $(if($fr){'VIDÉOS'}else{'VIDEOS'}) $(if($fr){'Les explications vidéo sont en préparation.'}else{'Video explainers are being prepared.'}) $(if($fr){'Nous ne prétendons pas qu&rsquo;une bibliothèque existe déjà. Voici les résumés écrits des premiers sujets prévus.'}else{'We do not claim a video library already exists. These are written summaries of the first planned topics.'}))+"<section class=`"section`"><div class=`"container grid three`"><article class=`"card`"><h2>$(if($fr){'Cartographier un workflow'}else{'Map a workflow'})</h2><p>$(if($fr){'Définir le début, la fin, les acteurs, les décisions, les systèmes et les exceptions.'}else{'Define the start, end, actors, decisions, systems, and exceptions.'})</p></article><article class=`"card`"><h2>$(if($fr){'Comprendre le ROI'}else{'Understand ROI'})</h2><p>$(if($fr){'Comparer temps récupéré, coût chargé, adoption, coûts récurrents et risques.'}else{'Compare recovered time, loaded cost, adoption, recurring cost, and risk.'})</p></article><article class=`"card`"><h2>$(if($fr){'Utiliser l&rsquo;IA avec discernement'}else{'Use AI deliberately'})</h2><p>$(if($fr){'Choisir les bons cas, garder les sources visibles et conserver une validation appropriée.'}else{'Choose appropriate cases, keep sources visible, and retain suitable review.'})</p></article></div></section>"}
Save-Page 'videos/index.html' (Page 'en' 'Explainer videos — Delta Operations' 'Written summaries for upcoming explainers on workflows, ROI, and practical AI.' '/videos/' '/fr/videos/' '' (VideosBody 'en'))
Save-Page 'fr/videos/index.html' (Page 'fr' 'Vidéos explicatives — Opérations Delta' 'Résumés écrits des prochaines vidéos sur workflows, ROI et IA pratique.' '/fr/videos/' '/videos/' '' (VideosBody 'fr'))

function PrivacyBody([string]$Lang){$fr=$Lang-eq'fr';return (PageHero $(if($fr){'AVIS'}else{'NOTICE'}) $(if($fr){'Confidentialité'}else{'Privacy'}) $(if($fr){'Une explication claire des renseignements traités par ce site.'}else{'A clear explanation of information processed by this website.'}))+"<section class=`"section`"><div class=`"container`" style=`"max-width:850px`"><div class=`"notice`"><strong>$(if($fr){'En bref'}else{'In short'}):</strong> $(if($fr){'aucun compte, témoin publicitaire ou analytique. Les outils restent locaux; la checklist utilise le stockage local pour votre progression.'}else{'no accounts, advertising cookies, or analytics. Tools stay local; the checklist uses local storage for progress.'})</div><h2>$(if($fr){'Formulaire de contact'}else{'Contact form'})</h2><p>$(if($fr){'Lorsque vous soumettez le formulaire, Formspree traite le nom, le courriel, l&rsquo;organisation, le message, la portée, la langue et le consentement afin de livrer la demande.'}else{'When submitted, Formspree processes name, email, organization, message, scope, language, and consent to deliver the request.'})</p><h2>$(if($fr){'Outils interactifs'}else{'Interactive tools'})</h2><p>$(if($fr){'Les réponses au diagnostic, au calculateur, à l&rsquo;audit et au cahier ne sont pas envoyées. La checklist sauvegarde uniquement son état dans le stockage local de votre navigateur.'}else{'Diagnostic, calculator, audit, and brief responses are not submitted. The checklist saves only its state in browser local storage.'})</p><h2>$(if($fr){'Demandes et conservation'}else{'Requests and retention'})</h2><p>$(if($fr){'Les renseignements sont utilisés pour répondre et conservés selon les besoins et obligations applicables. Pour accès, correction ou suppression, écrivez à'}else{'Information is used to respond and retained as needed for applicable obligations. For access, correction, or deletion, email'}) <a href=`"mailto:contact@deltaoperations.ca`">contact@deltaoperations.ca</a>.</p><h2>$(if($fr){'Sécurité'}else{'Security'})</h2><p>$(if($fr){'N&rsquo;envoyez pas de mots de passe, données financières, médicales ou autres renseignements hautement sensibles dans le formulaire.'}else{'Do not submit passwords, financial, medical, or other highly sensitive information through the form.'})</p><p class=`"hint`">$(if($fr){'Dernière mise à jour : 3 août 2026.'}else{'Last updated: August 3, 2026.'})</p></div></section>"}
Save-Page 'privacy/index.html' (Page 'en' 'Privacy — Delta Operations' 'Delta Operations website privacy notice.' '/privacy/' '/fr/confidentialite/' '' (PrivacyBody 'en'))
