function TermsBody([string]$Lang){$fr=$Lang-eq'fr';return (PageHero $(if($fr){'CONDITIONS'}else{'TERMS'}) $(if($fr){'Conditions d&rsquo;utilisation'}else{'Terms of use'}) $(if($fr){'Conditions applicables à l&rsquo;utilisation de ce site et de ses outils gratuits.'}else{'Terms applying to this website and its free tools.'}))+"<section class=`"section`"><div class=`"container`" style=`"max-width:850px`"><h2>$(if($fr){'Information générale'}else{'General information'})</h2><p>$(if($fr){'Le contenu et les outils sont fournis à titre informatif et ne constituent pas un engagement, une garantie de résultat ni un avis juridique, financier ou de sécurité.'}else{'Content and tools are informational and do not constitute an engagement, outcome guarantee, or legal, financial, or security advice.'})</p><h2>$(if($fr){'Estimations'}else{'Estimates'})</h2><p>$(if($fr){'Les scores et calculs dépendent des données saisies et d&rsquo;hypothèses simplifiées. Une analyse réelle doit considérer coûts récurrents, adoption, exceptions et risques.'}else{'Scores and calculations depend on entered data and simplified assumptions. A real assessment must consider recurring cost, adoption, exceptions, and risk.'})</p><h2>$(if($fr){'Propriété intellectuelle'}else{'Intellectual property'})</h2><p>$(if($fr){'Le contenu du site appartient à Opérations Delta ou est utilisé avec autorisation. Les modalités de propriété d&rsquo;un mandat sont définies dans l&rsquo;entente correspondante.'}else{'Website content belongs to Delta Operations or is used with permission. Project ownership terms are defined in the corresponding agreement.'})</p><h2>$(if($fr){'Contact'}else{'Contact'})</h2><p><a href=`"mailto:contact@deltaoperations.ca`">contact@deltaoperations.ca</a></p><p class=`"hint`">$(if($fr){'Dernière mise à jour : 3 août 2026.'}else{'Last updated: August 3, 2026.'})</p></div></section>"}
Save-Page 'terms/index.html' (Page 'en' 'Terms of use — Delta Operations' 'Terms applying to the Delta Operations website and free interactive tools.' '/terms/' '/fr/conditions-utilisation/' '' (TermsBody 'en'))
Save-Page 'fr/conditions-utilisation/index.html' (Page 'fr' 'Conditions d&rsquo;utilisation — Opérations Delta' 'Conditions applicables au site et aux outils gratuits d&rsquo;Opérations Delta.' '/fr/conditions-utilisation/' '/terms/' '' (TermsBody 'fr'))

function RedirectPage([string]$Target){return "<!doctype html><html lang=`"en`"><head><meta charset=`"utf-8`"><meta name=`"viewport`" content=`"width=device-width,initial-scale=1`"><meta http-equiv=`"refresh`" content=`"0; url=$Target`"><link rel=`"canonical`" href=`"https://www.deltaoperations.ca$Target`"><title>Redirecting — Delta Operations</title></head><body><p><a href=`"$Target`">Continue to Delta Operations</a></p></body></html>"}
$redirects=[ordered]@{
 'en/index.html'='/';'en/services/index.html'='/services/';'en/solutions/index.html'='/solutions/';'en/tools/index.html'='/tools/';'en/sectors/index.html'='/sectors/';'en/about/index.html'='/about/';'en/contact/index.html'='/contact/';'en/privacy/index.html'='/privacy/';
 'en/resources/index.html'='/resources/';'en/faq/index.html'='/faq/';'en/case-studies/index.html'='/case-studies/';'en/guides/index.html'='/guides/';'en/templates/index.html'='/templates/';'en/videos/index.html'='/videos/';'en/terms/index.html'='/terms/';
 'en/tools/workflow-diagnostic/index.html'='/tools/workflow-diagnostic/';'en/tools/roi-calculator/index.html'='/tools/roi-calculator/';'en/tools/sme-express-audit/index.html'='/tools/sme-express-audit/';'en/tools/requirements-brief-generator/index.html'='/tools/requirements-brief-generator/';'en/tools/digital-transformation-checklist/index.html'='/tools/digital-transformation-checklist/'
}
foreach($entry in $redirects.GetEnumerator()){Save-Page $entry.Key (RedirectPage $entry.Value)}
Save-Page 'privacy.html' (RedirectPage '/privacy/')

$notFound=@"
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Page not found — Delta Operations</title><meta name="robots" content="noindex"><link rel="icon" href="/favicon.png"><link rel="stylesheet" href="/assets/css/styles.css"></head><body>$(Header 'en' '')<main id="main"><section class="page-hero"><div class="container"><p class="eyebrow">404</p><h1>Page not found.</h1><p>The address may have changed. Choose a destination below.</p><div class="hero-actions"><a class="button" href="/">English home</a><a class="button secondary" href="/fr/" lang="fr">Accueil français</a></div></div></section></main>$(Footer 'en')<script src="/assets/js/main.js"></script></body></html>
"@
